ALTER TABLE public.bookings ADD COLUMN guests integer NOT NULL DEFAULT 2;
ALTER TABLE public.orders ADD COLUMN quantity integer NOT NULL DEFAULT 1, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_status_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_status_check CHECK (status IN ('pending','in_progress','ready','done','cancelled'));
ALTER TABLE public.invitation_emails ALTER COLUMN status SET DEFAULT 'afventer e-maildomæne';

CREATE TABLE public.guest_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE, room_number text NOT NULL, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.guest_feedback TO service_role;
ALTER TABLE public.guest_feedback ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.towels_used(_b uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(sum(quantity),0)::int FROM orders WHERE booking_id=_b AND type='towels' AND NOT cancelled AND status<>'cancelled' $$;
REVOKE ALL ON FUNCTION public.towels_used(uuid) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.guest_info(_b bookings,_device uuid) RETURNS json LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT json_build_object('access_token',_b.access_token,'device_id',_device,'guest_name',_b.guest_name,'room_number',_b.room_number,'reference',_b.reference,'capacity',r.capacity,'guests',_b.guests,'towel_limit',_b.guests,'towels_used',towels_used(_b.id),'max_devices',_b.guests+2,'devices',(SELECT count(*) FROM devices d WHERE d.booking_id=_b.id),'housekeeping_status',CASE WHEN r.cleaning_booking_id=_b.id THEN r.housekeeping_status ELSE 'occupied' END,'wifi_ssid',CASE WHEN now()>=_b.starts_at AND now()<_b.ends_at AND _b.active THEN (SELECT value FROM hotel_secrets WHERE key='wifi_ssid') END,'wifi_password',CASE WHEN now()>=_b.starts_at AND now()<_b.ends_at AND _b.active THEN (SELECT value FROM hotel_secrets WHERE key='wifi_password') END,'starts_at',_b.starts_at,'ends_at',_b.ends_at,'server_now',now(),'dinner_choice',_b.dinner_choice,'feedback_given',EXISTS(SELECT 1 FROM guest_feedback f WHERE f.booking_id=_b.id)) FROM rooms r WHERE r.number=_b.room_number $$;
REVOKE ALL ON FUNCTION public.guest_info(public.bookings,uuid) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.guest_order_towels(_token uuid,_device uuid,_qty integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; _id uuid; BEGIN b:=require_guest(_token,_device); IF _qty IS NULL OR _qty<1 OR towels_used(b.id)+_qty>b.guests THEN RAISE EXCEPTION 'TOWEL_LIMIT'; END IF; INSERT INTO orders(room_number,booking_id,type,details,quantity) VALUES(b.room_number,b.id,'towels',_qty||' håndklæder til bytte',_qty) RETURNING id INTO _id; RETURN _id; END $$;
CREATE OR REPLACE FUNCTION public.guest_order(_token uuid,_device uuid,_type text,_details text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; _id uuid; BEGIN b:=require_guest(_token,_device); IF _type<>'room_service' THEN RAISE EXCEPTION 'INVALID_ORDER'; END IF; INSERT INTO orders(room_number,booking_id,type,details) VALUES(b.room_number,b.id,_type,left(coalesce(_details,''),500)) RETURNING id INTO _id; RETURN _id; END $$;
CREATE OR REPLACE FUNCTION public.guest_cancel_order(_token uuid,_device uuid,_order uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); UPDATE orders SET cancelled=true,updated_at=now() WHERE id=_order AND booking_id=b.id AND NOT cancelled AND status IN ('pending','in_progress'); IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_CANCELLABLE'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.staff_set_order_status(_pin text,_order uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _status NOT IN ('pending','in_progress','ready','done') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF; UPDATE orders SET status=_status,updated_at=now() WHERE id=_order AND NOT cancelled AND status <> 'done'; END $$;
CREATE OR REPLACE FUNCTION public.guest_feedback(_token uuid,_device uuid,_rating integer,_comment text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); IF _rating NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'INVALID_RATING'; END IF; INSERT INTO guest_feedback(booking_id,room_number,rating,comment) VALUES(b.id,b.room_number,_rating,left(coalesce(_comment,''),1000)); END $$;
DROP FUNCTION IF EXISTS public.staff_mock_booking(text,text,text,text,timestamptz,timestamptz);
CREATE OR REPLACE FUNCTION public.staff_mock_booking(_pin text,_name text,_email text,_room text,_start timestamptz,_end timestamptz,_guests integer DEFAULT 2) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ref text; cap int; BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF trim(_name)='' OR _email NOT LIKE '%@%.%' THEN RAISE EXCEPTION 'INVALID_BOOKING'; END IF; SELECT capacity INTO cap FROM rooms WHERE number=_room; IF cap IS NULL OR _guests<1 OR _guests>cap THEN RAISE EXCEPTION 'INVALID_GUESTS'; END IF; IF EXISTS(SELECT 1 FROM bookings WHERE room_number=_room AND active AND starts_at<_end AND ends_at>_start) THEN RAISE EXCEPTION 'ROOM_BUSY'; END IF; ref:='HP-'||upper(substr(gen_random_uuid()::text,1,8)); INSERT INTO bookings(reference,room_number,guest_name,guest_email,starts_at,ends_at,guests) VALUES(ref,_room,left(trim(_name),100),left(_email,200),_start,_end,_guests); RETURN ref; END $$;
CREATE OR REPLACE FUNCTION public.staff_pms(_pin text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; RETURN json_build_object('bookings',(SELECT coalesce(json_agg(q),'[]'::json) FROM (SELECT id,reference,room_number,guest_name,guest_email,guests,starts_at,ends_at,active,dinner_choice FROM bookings ORDER BY starts_at DESC) q),'emails',(SELECT coalesce(json_agg(q),'[]'::json) FROM (SELECT e.id,e.recipient,e.subject,e.status,e.created_at,b.reference FROM invitation_emails e JOIN bookings b ON b.id=e.booking_id ORDER BY e.created_at DESC LIMIT 30) q),'feedback',(SELECT coalesce(json_agg(q),'[]'::json) FROM (SELECT id,room_number,rating,comment,created_at FROM guest_feedback ORDER BY created_at DESC LIMIT 30) q)); END $$;
REVOKE ALL ON FUNCTION public.guest_order_towels(uuid,uuid,integer),public.guest_feedback(uuid,uuid,integer,text),public.staff_mock_booking(text,text,text,text,timestamptz,timestamptz,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.guest_order_towels(uuid,uuid,integer),public.guest_feedback(uuid,uuid,integer,text),public.staff_mock_booking(text,text,text,text,timestamptz,timestamptz,integer),public.staff_pms(text),public.guest_order(uuid,uuid,text,text),public.guest_cancel_order(uuid,uuid,uuid),public.staff_set_order_status(text,uuid,text) TO anon,authenticated;